/*
 * A044426  Numbers n such that string 9,4 occurs in the base 10
 *          representation of n but not of n-1.
 * https://oeis.org/A044426
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   numbers n such that the decimal representation of n contains the
 *            substring "94" but n-1 does not. The sequence is generated by a
 *            simple scan of successive integers, storing already found terms
 *            for fast repeated look‑ups
 * Range:     u8 n <= 2, u16 n <= 39, u32 n <= 39, u64 n <= 39, u128 n <= 39,
 *            big any n
 * Helpers:   has94
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include "../utils/has94.h"

/* For arbitrary‑precision seq_t this code is compiled as C++11/14/17.
   It uses only integer arithmetic and deterministic memory layout. */

/* Cache of computed terms */
#define MAX_CACHE 20000   /* sufficient for n <= 10000 */
static seq_t cache[MAX_CACHE];
static idx_t cache_len = 0;   /* number of terms stored */
static seq_t next_test = 1;   /* next integer to test */

/* External function requested by the framework */
seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* undefined for the sequence, but harmless */

    /* Extend cache until it contains at least n terms */
    while (cache_len < n) {
        /* Ensure we stay within the allocated cache size */
        if (cache_len >= MAX_CACHE) {
            /* If more terms are needed than the static cache allows,
               fall back to scanning without storing further values. */
            seq_t cur = next_test;
            while (true) {
                if (has94(cur) && !has94(cur - 1)) {
                    if (++cache_len == n) return cur;
                }
                cur++;
            }
        }

        seq_t cur = next_test++;
        if (has94(cur) && !has94(cur - 1)) {
            cache[cache_len++] = cur;
        }
    }

    return cache[n - 1];
}
